// Guided reconstruction of L7–L10. Source identities are the dossier's section/assignment/final IDs.
// Numerical examples are recalculated below; new stories and transfer questions are pedagogical.
// Exam tasks are constructed training, never presented as official SSE questions or solutions.
import type { Check, Dim, Lesson } from './types';
import { actors, guidedLesson, type TeachingBlock } from './lesson-kit';
import type { LessonDiagramSpec } from './lesson-diagrams';

function choice(id: string, q: string, right: [string, string], wrong: [string, string][], dim: Dim = 'intuition'): Check {
  return { kind: 'choice', id, q, dim, tags: [], options: [
    { text: right[0], feedback: right[1], correct: true },
    ...wrong.map(([text, feedback]) => ({ text, feedback })),
  ] };
}
function num(id: string, q: string, answer: number, explain: string, traps: [number, string][] = [], unit = ''): Check {
  return { kind: 'numeric', id, q, answer, explain, dim: 'calculation', tags: [], unit, tol: 0.015,
    traps: traps.map(([value, feedback]) => ({ value, feedback })) };
}
function order(id: string, q: string, items: string[]): Check {
  return { kind: 'order', id, q, items, dim: 'intuition', tags: [], explain: items.join(' → ') };
}
function build(id: string, q: string, lhs: string, tokens: string[], accept: string[][], explain: string): Check {
  return { kind: 'build', id, q, lhs, tokens, accept, explain, dim: 'formula', tags: [] };
}
function words(id: string, q: string, rubric: { id: string; label: string; patterns: RegExp[] }[], model: string, lang: 'fr' | 'en' = 'fr'): Check {
  return { kind: 'text', id, q, rubric, model, lang, dim: lang === 'en' ? 'english' : 'intuition', tags: [] };
}
function block(id: string, title: string, human: string, economist: string, exam: string, why: string[], example: string, me: string, checks: Check[], refs: string[], extra: Partial<TeachingBlock> = {}): TeachingBlock {
  return { id, title, human, economist, exam, why, example, me, checks, refs, provenance: 'peda', ...extra };
}

